package com.monitoring.agent

import java.io.{File, FileWriter, BufferedWriter}
import java.nio.file.{Files, Paths, Path, StandardOpenOption}
import java.nio.channels.{FileChannel, FileLock}
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.concurrent.{ConcurrentHashMap, Executors, TimeUnit}
import java.util.concurrent.atomic.AtomicLong
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

object AuditConfig {
  val MAX_LOG_SIZE: Long = 10 * 1024 * 1024 // 10MB
  val ROTATION_CHECK_INTERVAL: Long = 5000 // ms
  val AUDIT_DIR: String = "/var/log/audit"
  val INTEGRITY_SUFFIX: String = ".sha256"

  // Secret key for HMAC-based integrity. Loaded from environment or a
  // securely provisioned source; must NOT be hard-coded in production.
  val INTEGRITY_KEY: Array[Byte] = {
    val fromEnv = Option(System.getenv("AUDIT_INTEGRITY_KEY"))
    fromEnv.map(_.getBytes("UTF-8")).getOrElse {
      throw new IllegalStateException(
        "AUDIT_INTEGRITY_KEY environment variable must be set for audit log integrity"
      )
    }
  }
}

case class AuditEvent(
  timestamp: Long,
  source: String,
  level: String,
  message: String,
  principal: Option[String] = None
)

trait IntegrityVerifier {
  def computeHash(content: Array[Byte]): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(AuditConfig.INTEGRITY_KEY, "HmacSHA256"))
    mac.doFinal(content).map("%02x".format(_)).mkString
  }

  def verifyFileIntegrity(filePath: Path): Boolean = {
    val hashPath = Paths.get(filePath.toString + AuditConfig.INTEGRITY_SUFFIX)
    if (!Files.exists(hashPath)) return true // first write
    val storedHash = new String(Files.readAllBytes(hashPath)).trim
    val currentHash = computeHash(Files.readAllBytes(filePath))
    constantTimeEquals(storedHash, currentHash)
  }

  private def constantTimeEquals(a: String, b: String): Boolean = {
    val ab = a.getBytes("UTF-8")
    val bb = b.getBytes("UTF-8")
    if (ab.length != bb.length) return false
    var result = 0
    var i = 0
    while (i < ab.length) {
      result |= ab(i) ^ bb(i)
      i += 1
    }
    result == 0
  }

  def updateIntegrityRecord(filePath: Path, content: Array[Byte]): Unit = {
    val hashPath = Paths.get(filePath.toString + AuditConfig.INTEGRITY_SUFFIX)
    val hash = computeHash(content)
    Files.write(hashPath, hash.getBytes, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)
  }
}

class AuditLogRotator extends IntegrityVerifier {
  private val rotationLock = new Object()
  private val lastRotation = new AtomicLong(System.currentTimeMillis())

  def shouldRotate(logFile: Path): Boolean = {
    if (!Files.exists(logFile)) return false
    Files.size(logFile) >= AuditConfig.MAX_LOG_SIZE
  }

  def rotateLog(logFile: Path): Try[Path] = Try {
    rotationLock.synchronized {
      val timestamp = System.currentTimeMillis()
      val rotatedName = s"${logFile.toString}.${timestamp}"
      val rotatedPath = Paths.get(rotatedName)
      Files.move(logFile, rotatedPath)
      Files.createFile(logFile)
      rotatedPath
    }
  }
}

class SecureAuditLogger extends IntegrityVerifier {
  private val rotator = new AuditLogRotator()
  private val writeCounter = new AtomicLong(0)
  private val activeStreams = new ConcurrentHashMap[String, BufferedWriter]()
  private val scheduler = Executors.newScheduledThreadPool(2)
  private val writeLock = new Object()

  def initialize(): Unit = {
    val auditDir = new File(AuditConfig.AUDIT_DIR)
    if (!auditDir.exists()) auditDir.mkdirs()
    scheduler.scheduleAtFixedRate(
      () => performRotationCheck(),
      AuditConfig.ROTATION_CHECK_INTERVAL,
      AuditConfig.ROTATION_CHECK_INTERVAL,
      TimeUnit.MILLISECONDS
    )
  }

  def logEvent(event: AuditEvent): Try[Unit] = {
    val logFile = resolveLogPath(event.source)
    validateAndWrite(logFile, event)
  }

  private def resolveLogPath(source: String): Path = {
    val sanitized = source.replaceAll("[^a-zA-Z0-9_-]", "_")
    Paths.get(AuditConfig.AUDIT_DIR, s"${sanitized}.audit.log")
  }

  private def validateAndWrite(logFile: Path, event: AuditEvent): Try[Unit] = Try {
    val filePath = logFile.toAbsolutePath.normalize()
    val auditBase = Paths.get(AuditConfig.AUDIT_DIR).toAbsolutePath.normalize()
    require(filePath.startsWith(auditBase), "Path traversal detected")

    writeLock.synchronized {
      // Atomic: Verify integrity and write within same critical section
      if (Files.exists(filePath)) {
        val integrityOk = verifyFileIntegrity(filePath)
        if (!integrityOk) {
          throw new SecurityException(s"Integrity violation detected for ${filePath}")
        }
      }

      val formatted = formatEvent(event)
      val existingContent = if (Files.exists(filePath)) {
        Files.readAllBytes(filePath)
      } else {
        Array.emptyByteArray
      }

      Files.write(
        filePath,
        formatted.getBytes,
        StandardOpenOption.CREATE,
        StandardOpenOption.APPEND
      )

      val newContent = existingContent ++ formatted.getBytes
      updateIntegrityRecord(filePath, newContent)

      writeCounter.incrementAndGet()
    }
  }

  private def formatEvent(event: AuditEvent): String = {
    val principal = event.principal.getOrElse("SYSTEM")
    s"[${event.timestamp}] [${event.level}] [${principal}] ${event.message}\n"
  }

  private def performRotationCheck(): Unit = {
    Try {
      val auditDir = Paths.get(AuditConfig.AUDIT_DIR)
      if (Files.exists(auditDir)) {
        writeLock.synchronized {
          Files.list(auditDir).filter(_.toString.endsWith(".audit.log")).forEach { logFile =>
            if (rotator.shouldRotate(logFile)) {
              rotator.rotateLog(logFile)
            }
          }
        }
      }
    }
  }

  def getWriteCount: Long = writeCounter.get()

  def shutdown(): Unit = {
    scheduler.shutdown()
    scheduler.awaitTermination(10, TimeUnit.SECONDS)
    activeStreams.values().forEach(_.close())
  }
}

object MonitoringAgent extends App {
  val logger = new SecureAuditLogger()
  logger.initialize()

  // Example usage
  val event = AuditEvent(
    timestamp = System.currentTimeMillis(),
    source = "auth-service",
    level = "INFO",
    message = "User login successful",
    principal = Some("admin@corp.local")
  )

  logger.logEvent(event) match {
    case Success(_) => println("Event logged successfully")
    case Failure(ex) => println(s"Failed to log event: ${ex.getMessage}")
  }
}
